      <div class="cc-seg ax-views" id="axViews" role="group" aria-label="View">${[["day","By day"],["agent","By agent"],["board","Summary"]].map(([t,i])=>`<button type="button" data-view="${t}" aria-pressed="${t===ka}">${i}</button>`).join("")}</div>
